function handleKeyDown(event: KeyboardEvent) {
  if (isUserTyping()) return;
  if (event.ctrlKey || event.altKey || event.metaKey) return;
  // ...
  const action = reverseShortcuts[keyStr];
  // Holding a key auto-repeats it: only step actions (volume, seek, speed, filters) follow along.
  if (event.repeat && (!action || !REPEATABLE_ACTIONS.has(action))) return;
  // ...
}

let activeElement = document.activeElement;
if (!activeElement) return false;
if (activeElement.hasAttribute(PLAYER_HOST_ATTR)) return false;
while (activeElement.shadowRoot?.activeElement) {
  activeElement = activeElement.shadowRoot.activeElement;
  if (activeElement.hasAttribute(PLAYER_HOST_ATTR)) return false;
}

