}

export function simulateClick(el: HTMLElement) {
  try { el.focus(); } catch {}
  const eventOptions = { bubbles: true, cancelable: true, view: window };
  el.dispatchEvent(new MouseEvent('mousedown', eventOptions));
  el.dispatchEvent(new MouseEvent('mouseup', eventOptions));
  el.click();
}

/** Sets style properties and returns a function that restores exactly the previous value and priority of each. */
function setStyles(el: HTMLElement, props: Record<string, string>, priority: string): () => void {
  const saved = Object.keys(props).map((name) => ({
    name,
    value: el.style.getPropertyValue(name),
    priority: el.style.getPropertyPriority(name),
  }));
  for (const [name, value] of Object.entries(props)) el.style.setProperty(name, value, priority);
  return () => {
    for (const { name, value, priority: p } of saved) {
      if (value) el.style.setProperty(name, value, p);
      else el.style.removeProperty(name);
    }
    if (el.getAttribute('style') === '') el.removeAttribute('style');
  };
}

