export function handleFilterStateRequest(
  message: any,
  _sender: unknown,
  sendResponse: (state: FilterState) => void,
): undefined {
  if (message?.type !== FILTER_STATE_REQUEST) return undefined;
  const video = getEnhancedSession()?.video ?? getActiveVideo();
  if (!video) return undefined;
  const state = getVideoFilterState(video);
  if (state.brightness !== 100 || state.contrast !== 100 || state.saturation !== 100) sendResponse(state);
  return undefined;
}

